<script setup>
import { ref, computed, onMounted } from "vue";
import { getMySubscription, requestPlanChange } from "@/services/admin";
import { learningAllowances, learningFeatures, packageDescriptions, packageStates } from "@/lib/packageCopy";
const data = ref(null), error = ref(""), loading = ref(false), submitting = ref(false), message = ref("");
const labels = Object.fromEntries(Object.entries(learningAllowances).map(([id, value]) => [id, value.label]));
const plan = computed(() => data.value?.plans[data.value.subscription.planId]);
async function load() { loading.value = true; error.value = ""; try { data.value = await getMySubscription(); } catch (e) { error.value = e.message; } finally { loading.value = false; } }
onMounted(load);
async function choose(planId) {
  submitting.value = true; error.value = ""; message.value = "";
  try { const r = await requestPlanChange(planId); data.value.planRequest = r.request; message.value = "Request submitted. Arrange payment with the administrator; your package changes after approval."; }
  catch (e) { error.value = e.message; } finally { submitting.value = false; }
}
</script>
<template>
  <section><div class="head"><div><p class="eyebrow">YOUR FAMILY'S LEARNING JOURNEY</p><h1>Choose your family's learning package</h1><p class="intro">A curriculum, learning activities, a family planner, and support as your child grows. Choose the collection of ready-to-use learning activities that fits your family.</p></div><button class="btn" :disabled="loading" @click="load">Refresh</button></div><p v-if="error" role="alert" class="error">{{ error }}</p>
    <template v-if="data">
      <p v-if="message" role="status">{{ message }}</p>
      <article v-if="data.planRequest" class="card"><h2>Package request · {{ data.planRequest.status }}</h2><p>{{ data.planRequest.planName }} — {{ data.planRequest.currency }} {{ data.planRequest.price.toLocaleString() }}</p><p v-if="data.planRequest.status === 'pending'">Awaiting superadmin review. Your current package stays unchanged until approval.</p><p v-if="data.planRequest.rejectionReason">{{ data.planRequest.rejectionReason }}</p></article>
      <article class="card current-package"><p class="eyebrow">YOUR CURRENT PACKAGE</p><h2>{{ data.subscription.effectiveStatus === 'pending' ? 'Choose a package to begin' : plan?.name }} <span class="package-state">{{ packageStates[data.subscription.effectiveStatus] || data.subscription.effectiveStatus }}</span></h2><p v-if="data.subscription.effectiveStatus !== 'active'">Choose a learning package below, arrange payment with the administrator, and start after approval. The trial is a paid introduction; every package requires activation.</p><p v-else>Your family's learning package is active until {{ new Date(data.subscription.endsAt).toLocaleString() }}.</p><p v-if="data.subscription.agreedPrice">Agreed price: {{ data.subscription.currency }} {{ data.subscription.agreedPrice.toLocaleString() }} · payment {{ data.subscription.paymentStatus }}</p>
        <div v-if="data.subscription.effectiveStatus !== 'pending'" class="activity-usage"><strong>{{ data.usage.activities || 0 }} / {{ plan?.limits.activities }} activities prepared</strong><p>New or refreshed activities in this package. Reuse saved activities for more practice.</p></div><details v-if="data.subscription.effectiveStatus !== 'pending'"><summary>Package limits and supporting allowances</summary><div class="allowance-table"><table><thead><tr><th>Learning support</th><th>Used / package allowance</th><th>Per day</th></tr></thead><tbody><tr v-for="(label, kind) in labels" :key="kind"><td>{{ label }}<small>{{ learningAllowances[kind].description }}</small></td><td>{{ data.usage[kind] || 0 }} / {{ plan?.limits[kind] }}</td><td>{{ plan?.daily[kind] }}</td></tr></tbody></table></div></details>
      </article>
      <div class="plans"><article v-for="(p, id) in data.plans" :key="id" class="card plan-card"><p class="eyebrow">{{ packageDescriptions[id]?.eyebrow }}</p><h2>{{ p.name }}</h2><p class="package-description">{{ packageDescriptions[id]?.description }}</p><div class="price"><strong>{{ p.currency }} {{ p.price.toLocaleString() }}</strong><span>for {{ p.durationDays }} day{{ p.durationDays === 1 ? '' : 's' }}</span></div><div class="activity-offer"><strong>Up to {{ p.limits.activities }}</strong><span>ready-to-use learning activities</span><small>New or refreshed, across your family, during this package.</small></div><ul class="package-benefits"><li>Learning content: exercises, stories, reading and practice</li><li>Clear parent guidance and worked examples</li><li>Illustrations where they support the activity</li><li>Personal curriculum, planner and progress tracking</li><li>Reuse saved activities for extra practice</li></ul><details><summary>What's included and how it works</summary><p class="allowance-explanation">{{ learningAllowances.activities.description }} Up to {{ p.daily.activities }} can be prepared per day, within your package total. A syllabus is a collection of activities; its size depends on your subjects and remaining allowance.</p><p class="allowance-explanation">Optional support: up to {{ p.limits.tts }} read-aloud recordings and {{ p.limits.liveMinutes }} learning companion minutes, with {{ p.sessionMinutes }} minutes per conversation.</p><p class="allowance-explanation">Supporting preparation limits: {{ p.limits.text }} requests and {{ p.limits.image }} illustration requests per package. Complex preparations and retries use these limits; contact the administrator if they prevent you from preparing your activities.</p></details><button class="btn primary" :disabled="submitting || loading || data.planRequest?.status === 'pending' || (data.subscription.effectiveStatus === 'active' && data.subscription.planId === id)" @click="choose(id)">{{ data.subscription.effectiveStatus === 'active' && data.subscription.planId === id ? 'Current package' : 'Request this package' }}</button></article></div>
      <div class="learning-included"><h2>A complete learning workspace, in every package</h2><p>Packages include access to the same learning tools. Duration and learning allowances differ.</p><div class="feature-grid"><article v-for="feature in learningFeatures" :key="feature.title"><h3>{{ feature.title }}</h3><p>{{ feature.description }}</p></article></div></div>
      <article class="card package-faq"><h2>Know exactly what you're choosing</h2><p><strong>What counts as an activity?</strong> One prepared item with learning content, such as a maths exercise, story, reading task or language practice. A successful refresh or a set of child-specific versions of that activity uses one activity allowance. Failed preparation does not use an activity allowance; supporting request limits still apply.</p><p><strong>How many courses or sessions?</strong> Activities are organized into your syllabus and planner. They are not fixed-length courses or teacher-led classes. You choose how to use them with your child.</p><p><strong>Shared across your family:</strong> The activity total covers all children and subjects together. Reusing saved content does not prepare a new activity.</p><p><strong>Payment and renewal:</strong> Request a package, arrange payment outside the app, then start after administrator approval. Approval or renewal starts a new allowance. Daily limits reset at midnight UTC.</p></article>
    </template>
  </section>
</template>
