ne-height:1.6; color:#80748b; margin-top:.4rem; }.allowance-table { overflow:auto; }table { min-width:500px; }.current-package details { margin-top:1.4rem; }@media(max-width:750px){.feature-grid{grid-template-columns:1fr}.package-description{min-height:0}.head h1{font-size:1.6rem}.head{flex-wrap:wrap}.package-state{margin:.6rem 0 0}}
